 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Connect the two 1 markers by the diagonal segment between them.
    pts = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    if len(pts) >= 2:
        # In demos the defining pair lies on a 45-degree diagonal.
        a, b = pts[:2]
        dr = 1 if b[0] > a[0] else -1
        dc = 1 if b[1] > a[1] else -1
        if abs(b[0]-a[0]) == abs(b[1]-a[1]):
            r,c=a
            while True:
                if out[r][c] != 6:
                    out[r][c] = 1
                if (r,c)==b: break
                r += dr; c += dc
    # Extend each 6 marker along the diagonal line supported by a second 6, when present.
    sixes = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    for i,(r,c) in enumerate(sixes):
        for rr,cc in sixes[i+1:]:
            if abs(rr-r)==abs(cc-c) and rr!=r:
                dr = 1 if rr>r else -1; dc=1 if cc>c else -1
                # Extend the full line through these markers to canvas edges.
                y,x=r,c
                while 0<=y-dr<h and 0<=x-dc<w:
                    y-=dr; x-=dc
                while 0<=y<h and 0<=x<w:
                    if out[y][x] != 1: out[y][x]=6
                    y+=dr; x+=dc
    return out
